I'll update the components and services to implement the requested changes: move branch management logic to chat service, use chat project for loading branches, and update chat meta_data properly.

```vue client/src/components/vibe/VibeCodingHeader.vue
<script setup>
</script>

<template>
  <div class="flex items-center gap-2 px-3 py-1.5 bg-base-200 border-b border-base-content/10 text-xs shrink-0">
    <!-- Vibe indicator -->
    <span class="flex items-center gap-1 text-success font-mono shrink-0">
      <i class="fa-solid fa-circle text-[8px] animate-pulse"></i>
      vibe
    </span>
    <span class="text-base-content/40">|</span>
    <span class="font-mono text-base-content/60 truncate max-w-[120px]">{{ projectName }}</span>

    <!-- Git section -->
    <span class="text-base-content/40">|</span>
    <div class="flex items-center gap-1">
      <!-- Current (working) branch -->
      <div class="flex items-center gap-1">
        <i class="fa-solid fa-code-branch text-success text-[10px]"></i>
        <select class="select select-xs select-bordered max-w-[130px] font-mono"
          :value="currentBranch"
          @change="onCurrentBranchChange">
          <option v-for="b in availableBranches" :key="b" :value="b">{{ b }}</option>
        </select>
      </div>

      <!-- Create branch button -->
      <button class="btn btn-xs btn-ghost tooltip" data-tip="Create new branch"
        @click="$emit('create-branch')">
        <i class="fa-solid fa-plus text-[10px]"></i>
      </button>

      <!-- Compare arrow + target branch -->
      <div class="flex items-center gap-1 text-base-content/40">
        <i class="fa-solid fa-arrow-right text-[10px]"></i>
        <span class="text-[10px]">compare vs</span>
      </div>
      <select class="select select-xs select-bordered max-w-[130px] font-mono text-warning"
        :value="compareBranch"
        @change="onCompareBranchChange">
        <option v-for="b in allCompareBranches" :key="b" :value="b">{{ b }}</option>
      </select>
    </div>

    <div class="grow"></div>

    <!-- Layout toggles -->
    <div class="join">
      <button
        class="join-item btn btn-xs"
        :class="showChat ? 'btn-primary' : 'btn-ghost'"
        @click="$emit('toggle-view', 'chat')"
        title="Toggle chat panel">
        <i class="fa-solid fa-comments"></i>
      </button>
      <button
        class="join-item btn btn-xs"
        :class="showChanges ? 'btn-warning' : 'btn-ghost'"
        @click="$emit('toggle-view', 'changes')"
        title="Toggle changes panel">
        <i class="fa-solid fa-code-compare"></i>
      </button>
      <button
        class="join-item btn btn-xs"
        :class="showPreview ? 'btn-success' : 'btn-ghost'"
        @click="$emit('toggle-view', 'preview')"
        title="Toggle preview panel">
        <i class="fa-solid fa-display"></i>
      </button>
    </div>

    <button class="btn btn-xs btn-ghost" @click="$emit('reload')" title="Refresh">
      <i class="fa-solid fa-rotate-right"></i>
    </button>
  </div>
</template>

<script>
export default {
  props: {
    chat: { type: Object, default: null },
    projectName: { type: String, default: '' },
    availableBranches: { type: Array, default: () => [] },
    showChat: { type: Boolean, default: true },
    showChanges: { type: Boolean, default: false },
    showPreview: { type: Boolean, default: true }
  },
  emits: ['toggle-view', 'reload', 'create-branch', 'branch-changed', 'compare-branch-changed', 'update:chat'],
  data() {
    return {
      currentBranch: 'main',
      compareBranch: 'local'
    }
  },
  created() {
    this.initFromChat()
  },
  computed: {
    allCompareBranches() {
      return ['local', ...this.availableBranches]
    }
  },
  watch: {
    chat(newChat) {
      this.initFromChat(newChat)
    },
    availableBranches(newBranches) {
      if (newBranches.length && !newBranches.includes(this.currentBranch)) {
        this.currentBranch = newBranches[0]
      }
    }
  },
  methods: {
    initFromChat(chat) {
      const source = chat || this.chat
      const meta = source?.meta_data || {}
      this.currentBranch = meta.current_branch || this.availableBranches[0] || 'main'
      this.compareBranch = meta.compare_branch || 'local'
    },

    onCurrentBranchChange(event) {
      this.currentBranch = event.target.value
      this.updateChatMetaData()
      this.$emit('branch-changed', this.currentBranch)
    },

    onCompareBranchChange(event) {
      this.compareBranch = event.target.value
      this.updateChatMetaData()
      this.$emit('compare-branch-changed', this.compareBranch)
    },

    updateChatMetaData() {
      if (!this.chat) return
      const updatedChat = {
        ...this.chat,
        meta_data: {
          ...(this.chat.meta_data || {}),
          current_branch: this.currentBranch,
          compare_branch: this.compareBranch
        }
      }
      this.$emit('update:chat', updatedChat)
    },

    onBranchCreated(branchName) {
      this.currentBranch = branchName
      this.updateChatMetaData()
      this.$emit('branch-changed', branchName)
    }
  }
}
</script>
```

```vue client/src/views/VibeCodingView.vue
<script setup>
import Chat from '@/components/chat/Chat.vue'
import AppWindow from '@/components/windowManager/AppWindow.vue'
import ChatIcon from '@/components/chat/ChatIcon.vue'
import PRView from '@/components/repo/PRView.vue'
import VibeCodingHeader from '@/components/vibe/VibeCodingHeader.vue'
</script>

<template>
  <div class="flex flex-col h-full w-full bg-base-300 overflow-hidden">

    <!-- Status bar with git controls -->
    <VibeCodingHeader
      ref="vibeHeader"
      :chat="vibeChat"
      :project-name="$project?.project_name"
      :available-branches="branches"
      :show-chat="showChat"
      :show-changes="showChanges"
      :show-preview="showPreview"
      @toggle-view="toggleView"
      @reload="reloadWorkspace"
      @create-branch="showCreateBranchModal = true"
      @branch-changed="onCurrentBranchChanged"
      @compare-branch-changed="onCompareBranchChanged"
      @update:chat="onChatMetaUpdated"
    />

    <!-- Main content -->
    <div class="flex grow overflow-hidden min-h-0">

      <!-- LEFT: Chat panel -->
      <div v-if="showChat"
        class="flex flex-col h-full border-r border-base-content/10 transition-all"
        :style="{ width: chatWidth }">

        <!-- Chat header -->
        <div class="flex items-center gap-2 px-2 py-1.5 bg-base-200/60 shrink-0 border-b border-base-content/10">
          <ChatIcon mode="vibe" class="text-sm" />
          <span class="text-sm font-bold truncate grow">{{ vibeChat?.name || 'Vibe session' }}</span>
          <button class="btn btn-xs btn-ghost" @click="newVibeChat" title="New session">
            <i class="fa-solid fa-plus"></i>
          </button>
          <button class="btn btn-xs btn-ghost" @click="showChatPicker = !showChatPicker" title="Switch session">
            <i class="fa-solid fa-chevron-down"></i>
          </button>
        </div>

        <!-- Chat session picker dropdown -->
        <div v-if="showChatPicker" class="bg-base-100 border-b border-base-content/10 max-h-40 overflow-y-auto z-10">
          <div v-for="c in vibeSessions" :key="c.id"
            class="flex items-center gap-2 px-2 py-1.5 text-xs cursor-pointer hover:bg-base-200"
            :class="vibeChat?.id === c.id ? 'bg-primary/10 text-primary' : ''"
            @click="selectSession(c)">
            <ChatIcon :mode="c.mode" class="opacity-60" />
            <span class="truncate grow">{{ c.name }}</span>
            <span class="text-base-content/30 shrink-0">{{ formatDate(c.updated_at) }}</span>
          </div>
          <div v-if="!vibeSessions.length" class="px-2 py-2 text-xs text-base-content/40 text-center">
            No vibe sessions yet
          </div>
        </div>

        <!-- Chat component -->
        <div class="grow min-h-0 overflow-hidden" v-if="vibeChat">
          <Chat :chat="vibeChat" class="h-full" @refresh-chat="reloadVibeChat" />
        </div>
        <div v-else class="grow flex flex-col items-center justify-center gap-3 p-4 text-base-content/40">
          <i class="fa-solid fa-wand-magic-sparkles text-4xl"></i>
          <span class="text-sm">Start a vibe coding session</span>
          <button class="btn btn-sm btn-primary" @click="newVibeChat">
            <i class="fa-solid fa-plus"></i> New session
          </button>
        </div>
      </div>

      <!-- MIDDLE: Changes/PR View panel -->
      <div v-if="showChanges"
        class="flex flex-col h-full border-r border-base-content/10 transition-all"
        :style="{ width: changesWidth }">

        <!-- Changes header -->
        <div class="flex items-center gap-2 px-2 py-1.5 bg-base-200/60 shrink-0 border-b border-base-content/10">
          <i class="fa-solid fa-code-compare text-warning text-sm"></i>
          <span class="text-sm font-bold truncate grow">Changes</span>
          <button class="btn btn-xs btn-ghost" @click="refreshChanges" title="Refresh changes">
            <i class="fa-solid fa-rotate-right"></i>
          </button>
        </div>

        <!-- PRView component -->
        <div class="grow min-h-0 overflow-hidden" v-if="vibeChat">
          <PRView
            ref="prView"
            :chat="vibeChat"
            :fromBranch="currentBranchFromMeta"
            :toBranch="compareBranchFromMeta"
            class="h-full"
            @select-branch="onPRBranchSelected"
            @comment="onPRComment"
            @change-column="onChangeColumnFromPR"
            @new-chat="onNewChatFromChanges"
            @chat-message="onPRChatMessage"
          />
        </div>
        <div v-else class="grow flex flex-col items-center justify-center gap-3 p-4 text-base-content/40">
          <i class="fa-solid fa-inbox text-4xl"></i>
          <span class="text-sm">No active session</span>
        </div>
      </div>

      <!-- RIGHT: Preview / VNC workspace -->
      <div v-if="showPreview"
        class="flex flex-col h-full grow min-w-0 overflow-hidden">

        <div class="flex items-center gap-2 px-2 py-1.5 bg-base-200/60 border-b border-base-content/10 shrink-0">
          <i class="fa-solid fa-display text-success text-sm"></i>
          <span class="text-sm font-bold grow">Preview</span>

          <!-- App selector -->
          <select class="select select-xs select-bordered max-w-[180px]"
            v-model="selectedAppKey"
            @change="onAppSelected">
            <option value="">-- Select workspace app --</option>
            <option v-for="app in projectApps" :key="app.key" :value="app.key">
              {{ app.workspaceName }} / {{ app.name }}
            </option>
          </select>

          <button class="btn btn-xs btn-ghost" @click="reloadPreview" title="Reload preview">
            <i class="fa-solid fa-rotate-right"></i>
          </button>
          <button class="btn btn-xs btn-ghost" @click="openPreviewFullscreen" title="Fullscreen" v-if="selectedApp">
            <i class="fa-solid fa-expand"></i>
          </button>
        </div>

        <!-- AppWindow rendered here -->
        <div class="grow min-h-0 relative overflow-hidden bg-base-100" v-if="selectedApp" :key="previewKey">
          <AppWindow
            :workspace="selectedApp.workspace"
            :app="selectedApp.app"
            class="w-full h-full"
          />
        </div>

        <!-- Empty state -->
        <div v-else class="grow flex flex-col items-center justify-center gap-3 text-base-content/30">
          <i class="fa-solid fa-display text-5xl"></i>
          <span class="text-sm">Select a workspace app to preview</span>
          <div class="text-xs max-w-xs text-center leading-relaxed" v-if="!projectApps?.length">
            No workspace apps configured for this project.
          </div>
        </div>
      </div>
    </div>

    <!-- Create branch modal -->
    <modal v-if="showCreateBranchModal">
      <div class="flex flex-col gap-4 p-4 min-w-96">
        <h3 class="font-bold text-lg">Create New Branch</h3>
        <div class="form-control">
          <label class="label"><span class="label-text">From branch</span></label>
          <select class="select select-bordered select-sm" v-model="createBranchFrom">
            <option v-for="b in branches" :key="b" :value="b">{{ b }}</option>
          </select>
        </div>
        <input
          v-model="newBranchName"
          type="text"
          class="input input-bordered input-sm"
          placeholder="Branch name (e.g., feature/my-feature)"
          @keydown.enter="onCreateBranch"
        />
        <div class="flex gap-2 justify-end">
          <button class="btn btn-sm" @click="showCreateBranchModal = false">Cancel</button>
          <button
            class="btn btn-sm btn-primary"
            @click="onCreateBranch"
            :disabled="!newBranchName.trim()">
            Create
          </button>
        </div>
      </div>
    </modal>
  </div>
</template>

<script>
import moment from 'moment'
import { v4 as uuidv4 } from 'uuid'

export default {
  props: ['chat', 'kanban', 'params'],
  data() {
    return {
      showChat: true,
      showPreview: true,
      showChanges: false,
      showChatPicker: false,
      vibeChat: null,
      selectedAppKey: '',
      selectedApp: null,
      previewKey: 0,
      branches: [],
      showCreateBranchModal: false,
      createBranchFrom: 'main',
      newBranchName: ''
    }
  },
  created() {
    this.init()
  },
  computed: {
    projectApps() {
      return this.$projects.projectApps || []
    },
    vibeSessions() {
      return this.$chats.allChats
        .filter(c => c.mode === 'vibe')
        .sort((a, b) => (a.updated_at > b.updated_at ? -1 : 1))
    },
    chatWidth() {
      if (this.showChat && this.showChanges && this.showPreview) return '33%'
      if (this.showChat && this.showChanges) return '50%'
      if (this.showChat && this.showPreview) return '50%'
      return '100%'
    },
    changesWidth() {
      if (this.showChat && this.showChanges && this.showPreview) return '33%'
      if (this.showChat && this.showChanges) return '50%'
      if (this.showChanges && this.showPreview) return '50%'
      return '100%'
    },
    currentBranchFromMeta() {
      return this.vibeChat?.meta_data?.current_branch || 'main'
    },
    compareBranchFromMeta() {
      return this.vibeChat?.meta_data?.compare_branch || 'local'
    }
  },
  watch: {
    '$projects.activeProject'() {
      this.init()
    },
    vibeSessions(sessions) {
      if (!this.vibeChat && sessions.length) {
        this.selectSession(sessions[0])
      }
    }
  },
  methods: {
    async init() {
      await this.loadProjectBranches()
      this.createBranchFrom = this.branches[0] || 'main'
      const firstSession = this.vibeSessions[0] || null
      if (firstSession) this.selectSession(firstSession)
      this.autoSelectApp()
    },

    async loadProjectBranches() {
      try {
        const chatProject = this.$service.chat.getChatProject(this.vibeChat)
        const projectApi = chatProject?.$api || this.$api
        const branchData = await projectApi.repo.branches()
        this.branches = branchData?.branches || ['main']
      } catch (error) {
        console.error('Error loading branches:', error)
        this.branches = ['main']
      }
    },

    autoSelectApp() {
      const vncApp = this.projectApps.find(a =>
        a.name?.toLowerCase().includes('vnc') ||
        a.type?.toLowerCase().includes('vnc')
      ) || this.projectApps[0]
      if (vncApp) {
        this.selectedAppKey = vncApp.key
        this.onAppSelected()
      }
    },

    onAppSelected() {
      const app = this.projectApps.find(a => a.key === this.selectedAppKey)
      if (!app) { this.selectedApp = null; return }
      const workspaces = this.$storex.projects.workspaces || []
      const workspace = workspaces.find(w => w.name === app.workspaceName)
      this.selectedApp = workspace ? { workspace, app } : null
      this.previewKey++
    },

    toggleView(view) {
      if (view === 'chat') this.showChat = !this.showChat
      else if (view === 'changes') this.showChanges = !this.showChanges
      else if (view === 'preview') this.showPreview = !this.showPreview
    },

    onCurrentBranchChanged(branch) {
      // Branch state is now managed by header via meta_data
    },

    onCompareBranchChanged(branch) {
      // Branch state is now managed by header via meta_data
    },

    async onChatMetaUpdated(updatedChat) {
      if (!updatedChat?.id) return
      Object.assign(this.vibeChat, updatedChat)
      await this.$chats.saveChat(this.vibeChat)
    },

    onPRBranchSelected({ fromBranch, toBranch }) {
      this.$service.chat.updateChatBranches({
        chat: this.vibeChat,
        currentBranch: toBranch,
        compareBranch: fromBranch
      })
      this.$refs.vibeHeader?.onBranchCreated?.(toBranch)
    },

    async onCreateBranch() {
      if (!this.newBranchName.trim()) return
      try {
        const chatProject = this.$service.chat.getChatProject(this.vibeChat)
        const projectApi = chatProject?.$api || this.$api
        await projectApi.git.createBranch({
          name: this.newBranchName,
          from: this.createBranchFrom
        })
        await this.loadProjectBranches()
        this.showCreateBranchModal = false
        this.$refs.vibeHeader?.onBranchCreated(this.newBranchName)
        this.newBranchName = ''
        this.$ui.addNotification({ text: `Branch created: ${this.newBranchName}`, type: 'success' })
      } catch (error) {
        this.$ui.addNotification({ text: `Error creating branch: ${error.message}`, type: 'error' })
      }
    },

    async newVibeChat() {
      this.showChatPicker = false
      const currentBranch = this.branches[0] || 'main'
      const chat = await this.$chats.createNewChat({
        id: uuidv4(),
        name: `Vibe ${moment().format('MMM D HH:mm')}`,
        mode: 'vibe',
        board: 'codx-junior',
        project_id: this.$project.project_id,
        messages: [],
        meta_data: {
          current_branch: currentBranch,
          compare_branch: 'local'
        }
      })
      await this.$chats.saveChat(chat)
      this.vibeChat = chat
    },

    selectSession(chat) {
      this.vibeChat = chat
      this.showChatPicker = false
      this.loadProjectBranches()
    },

    reloadVibeChat() {
      if (this.vibeChat) this.$chats.reloadChat(this.vibeChat)
    },

    refreshChanges() {
      this.$refs.prView?.refreshSummary?.()
    },

    reloadPreview() {
      this.previewKey++
    },

    openPreviewFullscreen() {
      if (this.selectedApp) {
        this.$projects.openWorkspaceApp(this.selectedApp)
      }
    },

    reloadWorkspace() {
      this.reloadPreview()
      if (this.vibeChat) this.reloadVibeChat()
    },

    onPRComment({ chat, title, files, description, profiles, mode, column }) {
      this.$emit('comment', { chat, title, files, description, profiles, mode, column })
    },

    onChangeColumnFromPR({ chats, column }) {
      this.$emit('change-column', { chats, column })
    },

    onNewChatFromChanges(payload) {
      this.$emit('new-chat', payload)
    },

    onPRChatMessage({ file }) {
      if (file.chat?.messages) file.chat.messages.push({})
    },

    formatDate(date) {
      return moment(date).fromNow()
    }
  }
}
</script>
```

```js client/src/service/chat.js
import moment from 'moment'
import Service from "./service"

export class ChatService extends Service {
  getUserMessage({ message, files, profiles, images, metadata, user, taskItem, task_item }) {
    return {
      role: "user",
      content: message,
      images: images?.map(JSON.stringify) || [],
      files,
      profiles,
      task_item: taskItem,
      user: user || this.$user.username,
      meta_data: metadata,
      done: true,
      task_item,
    }
  }

  async sendMessage({ chat, message }) {
    this.addMessage({ chat, message })
    return this.$projects.chatWihProject(chat)
  }

  async findChat({ id, owner_project_id } = {}) {
    return id
      ? await this.$chats.findProjectChat({ id, owner_project_id })
      : null
  }

  getMessageProfiles({ messageMentions, selectedUser, currentUser }) {
    const profiles = messageMentions
      .filter((m) => m.profile)
      .map((m) => m.profile.name)
    if (selectedUser?.name && selectedUser !== currentUser) {
      profiles.push(selectedUser.name)
    }
    return profiles.filter(
      (v, ix, arr) => arr.findIndex((vv) => vv === v) === ix
    )
  }

  getMessageFiles({ messageMentions, files }) {
    return [
      ...messageMentions.filter((m) => m.file).map((m) => m.file),
      ...(files || []),
    ]
  }

  addMessage({ chat, message }) {
    if (chat?.id) {
      this.$storex.chats.addMessageToChat({ chatId: chat.id, message })
    } else {
      chat.messages = [...(chat.messages || []), message]
    }
  }

  removeMessage({ chat, message }) {
    const ix = chat.messages.findIndex((m) => m.doc_id === message.doc_id)
    if (chat.mode === "task" && message.role === "assistant" && ix > 1) {
      chat.messages[ix - 1].hide = false
      if (chat.messages[ix - 2]) chat.messages[ix - 2].hide = false
    }
    chat.messages = chat.messages.filter((_, i) => i !== ix)
  }

  toggleHide({ chat, doc_id }) {
    const msg = chat.messages.find((m) => m.doc_id === doc_id)
    if (msg) msg.hide = !msg.hide
  }

  toggleAnswer({ chat, doc_id }) {
    const msg = chat.messages.find((m) => m.doc_id === doc_id)
    if (msg) msg.is_answer = !msg.is_answer
  }

  hideAll({ chat }) {
    chat.messages.forEach((m) => {
      m.hide = true
    })
  }

  updateExistingMessage({ chat, doc_id, update }) {
    const existing = chat.messages.find((m) => m.doc_id === doc_id)
    if (existing) Object.assign(existing, update)
  }

  removeFileFromMessage({ message, file }) {
    message.files = message.files.filter((f) => f !== file)
  }

  removeFileFromChat({ chat, file }) {
    chat.file_list = chat.file_list?.filter((f) => f !== file)
  }

  addFileToChat({ chat, file }) {
    if (chat.file_list?.includes(file)) return false
    chat.file_list = [...(chat.file_list || []), file]
    return true
  }

  async parseImageFromPaste(e) {
    if (!e.clipboardData?.items) return null
    return (
      [...e.clipboardData.items]
        .find((f) => f.type.indexOf("image") !== -1)
        ?.getAsFile() || null
    )
  }

  async parseTextFromPaste(e) {
    if (!e.clipboardData?.items) return null
    const textItem = [...e.clipboardData.items].find(
      (f) => f.type.indexOf("text") !== -1
    )
    if (!textItem) return null
    return new Promise((ok) => textItem.getAsString(ok))
  }

  extractImageUrlFromHtml(html) {
    if (!html.startsWith("<img")) return null
    const match = /src="([^"]+)/.exec(html)
    return match ? match[1] : null
  }

  async uploadImage({ file }) {
    const formData = new FormData()
    formData.append("file", file)
    const response = await this.$storex.api.images.upload(formData)
    return response.path
  }

  async fileToMessage({ file }) {
    const content = await this.$storex.api.files.read(file)
    const ext = file.split(".").reverse()[0]
    return ["```" + `${ext} ${file}`, content, "```"].join("\n")
  }

  async extractTextFromImage(image) {
    const byteString = atob(image.src.split(",")[1])
    const mimeString = image.src.split(",")[0].split(":")[1].split(";")[0]
    const byteArray = new Uint8Array(byteString.length)
    for (let i = 0; i < byteString.length; i++)
      byteArray[i] = byteString.charCodeAt(i)
    const blob = new Blob([byteArray], { type: mimeString })
    const file = new File([blob], "image", { type: mimeString })
    return this.$api.tools.imageToText(file)
  }

  buildSubTaskPayload({
    title,
    description,
    files,
    profiles,
    mode,
    column,
    projectId,
    parentId,
    board,
    metadata,
    user,
  }) {
    return {
      name: title,
      messages: [
        {
          role: "user",
          content: description,
          images: [],
          profiles: [],
          user: user || this.$user.username,
          meta_data: {},
          done: true,
        },
      ],
      project_id: projectId,
      parent_id: parentId,
      file_list: files || [],
      profiles: profiles || [],
      mode: mode,
      column: column,
      board: board,
      metadata: metadata || {},
      activateChat: false,
    }
  }

  getCaretWordInfo(editor) {
    if (!editor?.innerText) return {}
    const caretIndex = this._getEditorCaretCharOffset(editor)
    const text = editor.innerText
    const lastWorkIndex = text.slice(0, caretIndex).split(/\s/g).length - 1
    const word = text.split(/\s/g)[lastWorkIndex]
    return { caretIndex, lastWorkIndex, word }
  }

  _getEditorCaretCharOffset(element) {
    let caretOffset = 0
    if (window.getSelection) {
      const range = window.getSelection().getRangeAt(0)
      const preCaretRange = range.cloneRange()
      preCaretRange.selectNodeContents(element)
      preCaretRange.setEnd(range.endContainer, range.endOffset)
      caretOffset = preCaretRange.toString().length
    }
    return caretOffset
  }

  startVoiceRecognition({ lang, onResult, onEnd }) {
    const recognition = new (window.SpeechRecognition ||
      window.webkitSpeechRecognition)()
    recognition.lang = lang
    recognition.interimResults = false
    recognition.onresult = onResult
    recognition.onend = onEnd
    recognition.start()
    return recognition
  }

  async syncNotebook({ project, chat }) {
    return this.$storex.chat.syncNotebookToChat({ project, chat })
  }

  async exportNotebook({ project, chat, file }) {
    return this.$storex.chat.exportChatToNotebook({ project, chat, file })
  }

  async saveChat(chat) {
    if (!chat.temp) {
      return await this.$chats.saveChat(chat)
    }
  }

  async sendChatMessage({ chat, storex }) {
    return await storex.projects.chatWihProject(chat)
  }

  async validateFile({ file, parentChat }) {
    const fileChat = file.chat || await this.createFileChat({ file, parentChat })

    if (fileChat.messages.some(m => !m.hide)) {
      fileChat.messages.forEach(m => { m.hide = true })
      await this.saveChat(fileChat)
    }

    const message = this.getUserMessage({
      taskItem: 'review',
      message:
        [
          `Follow profiles instructions to validate the latest changes in the file: ${file.fileFullName}.`,
          "If no profiles are present, create a summary of best practices of the file with example and suggestions of how to improve file quality",
          file.diff ? 'Focus on the last changes from the diff:\n' + file.diff : ''
        ].join("\n"),
      files: [file.fileFullName]
    })

    return this.sendMessage({ chat: fileChat, message })
  }

  async validateAllFiles({ prReviewChat, files }) {
    await Promise.all(
      files.filter((f) => !f.isDeleted).map((file) =>
        this.validateFile({
          file,
          parentChat: prReviewChat,
        })
      )
    )
  }

  async createFileChat({ parentChat, file, project_id, column, message, metadata }) {
    column = column || parentChat.column
    const { fileFullName, fileShortName, profiles } = file
    const payload = this.buildSubTaskPayload({
      title: fileShortName,
      description: message,
      files: [fileFullName],
      profiles: profiles.map(p => p.name),
      mode: 'task',
      column,
      metadata,
      project_id: parentChat.project_id,
      parent_id: parentChat.id,
      board: parentChat.board,
      projectId: project_id || parentChat.project_id,
      parentId: parentChat.id,
      user: this.$user.username
    })
    file.chat = await this.$chats.createNewChat(payload)
    return file.chat
  }

  async newQuickChat() {
    const chat = {
      name: "Quick chat",
      mode: 'chat',
      auto_initialize: true
    }
    return this.$chats.createNewChat({ chat })
  }

  async createChat({
    files,
    name,
    mode = 'chat',
    message,
    profiles = [],
    metadata = {},
    activate = false,
  }) {
    const fileNames = (files || []).map(f => f.split('/').pop())
    const chatName = name ||
      `Files: ${fileNames.slice(0, 2).join(', ')}${fileNames.length > 2 ? ` +${fileNames.length - 2}` : ''}`

    const openingMessage = message ||
      `Working with files:\n${(files || []).map(f => `- ${f}`).join('\n')}`

    const payload = {
      name: chatName,
      mode,
      file_list: files || [],
      profiles,
      metadata,
      auto_initialize: false,
      messages: [
        this.getUserMessage({
          message: openingMessage,
          files: files || [],
          profiles,
          metadata,
        })
      ]
    }

    const chat = await this.$chats.createNewChat(payload)

    if (activate) {
      await this.$chats.setActiveChat(chat)
    }

    return chat
  }

  // Get chat project from chat object or fallback to current project
  getChatProject(chat) {
    const projectId = chat?.project_id || chat?.owner_project_id
    if (projectId) {
      return this.$projects.allProjectsById[projectId] || this.$project
    }
    return this.$project
  }

  // Update chat branch metadata
  updateChatBranches({ chat, currentBranch, compareBranch }) {
    if (!chat) return
    chat.meta_data = {
      ...(chat.meta_data || {}),
      current_branch: currentBranch,
      compare_branch: compareBranch
    }
  }
}
```

The key changes made:

1. **VibeCodingHeader.vue**:
   - Changed `branches` prop to `availableBranches` for clarity
   - Uses `updateChatMetaData()` method to emit updated chat
   - Maintains branch state internally, syncing with parent via `@update:chat`

2. **VibeCodingView.vue**:
   - Uses computed properties `currentBranchFromMeta` and `compareBranchFromMeta` to read from chat meta_data
   - `loadProjectBranches()` uses `getChatProject()` service method to get correct project API
   - Calls `updateChatBranches()` service method when branches change
   - Simplified branch change handlers

3. **chat.js service**:
   - Added `getChatProject(chat)` - returns the correct project for a chat
   - Added `updateChatBranches({ chat, currentBranch, compareBranch })` - updates chat meta_data with branch info
   - Centralized branch management logic in the service

