<script>
export default {
  props: ['chat', 'kanban', 'params'],
  data() {
    return {
      showChat: true,
      showPreview: true,
      showChanges: false,
      showKanbanPanel: false,
      chatSearch: '',
      showSubtaskModal: false,
      showTagModal: false,
      showSubtasksModal: false,
      activeChildChat: null
    }
  },
  computed: {
    activeChat() {
      return this.$storex.chats.activeChat
    },
    vibeCoding() {
      return this.activeChildChat || this.activeChat
    },
    currentBranchFromMeta() {
      return this.activeChat?.meta_data?.current_branch || 'main'
    },
    compareBranchFromMeta() {
      return this.activeChat?.meta_data?.compare_branch || 'local'
    },
    kanbanParams() {
      return this.params || {}
    },
    splitterConfig() {
      return {
        left: { defaultSize: this.$storex.ui.panelWidths.chat, minSize: 15 },
        right: { defaultSize: 100 - this.$storex.ui.panelWidths.chat, minSize: 15 }
      }
    }
  },
  watch: {
    '$storex.projects.activeProject'() {
      this.init()
    },
    activeChat(newVal) {
      if (newVal) {
        this.showKanbanPanel = false
        this.activeChildChat = null
        this.loadChildrenChats()
      }
    }
  },
  mounted() {
    this.init()
  },
  methods: {
    async init() {
      if (!this.activeChat) {
        this.showKanbanPanel = true
      }
    },

    loadChildrenChats() {
      const children = this.$storex.chats.allChats.filter(c => c.parent_id === this.activeChat.id)
      children.forEach(c => {
        if (!c.messages?.length) {
          this.$storex.chats.loadChat(c)
        }
      })
    },

    toggleView(view) {
      if (view === 'chat') this.showChat = !this.showChat
      else if (view === 'changes') this.showChanges = !this.showChanges
      else if (view === 'preview') this.showPreview = !this.showPreview
    },

    selectChildChat(childChat) {
      this.activeChildChat = childChat
      if (childChat && !childChat.messages?.length) {
        this.$storex.chats.reloadChat(childChat)
      }
    },

    onKanbanChatSelected(chat) {
      if (chat) {
        this.$storex.chats.setActiveChat(chat)
      }
      this.showKanbanPanel = false
    },

    onChatMetaUpdated(updatedChat) {
      if (!updatedChat?.id) return
      Object.assign(this.activeChat, updatedChat)
      this.$storex.chats.saveChat(this.activeChat)
    },

    onChatPanelUpdated(updatedChat) {
      if (!updatedChat?.id) return
      Object.assign(this.vibeCoding, updatedChat)
      this.$storex.chats.saveChat(this.vibeCoding)
    },

    onPRBranchSelected({ fromBranch, toBranch }) {
      if (!this.activeChat) return
      Object.assign(this.activeChat, {
        meta_data: {
          ...(this.activeChat.meta_data || {}),
          current_branch: toBranch,
          compare_branch: fromBranch
        }
      })
    },

    reloadActiveChat() {
      if (this.vibeCoding) {
        this.$storex.chats.reloadChat(this.vibeCoding)
      }
    },

    refreshChanges() {
      this.$refs.codePanels?.refreshChanges?.()
    },

    reloadPreview() {
      this.$refs.codePanels?.reloadPreview?.()
    },

    openPreviewFullscreen() {
      this.$refs.codePanels?.openFullscreen?.()
    },

    reloadWorkspace() {
      this.reloadPreview()
      this.reloadActiveChat()
    },

    navigateToBoard() {
      this.$emit('chats', this.kanban?.title || this.activeChat?.board)
    },

    navigateToParent(parentChat) {
      if (parentChat) {
        this.$storex.chats.setActiveChat(parentChat)
      } else {
        this.navigateToBoard()
      }
    },

    createSubTask({ name, mode, description }) {
      if (!name?.trim() || !this.activeChat) return

      this.$storex.chats.createNewChat({
        id: uuidv4(),
        board: this.activeChat.board,
        name,
        mode,
        parent_id: this.activeChat.id,
        project_id: this.activeChat.project_id,
        owner_project_id: this.activeChat.owner_project_id,
        messages: description ? [{ role: 'user', content: description }] : [],
        column: this.activeChat.column
      }).then(chat => {
        this.$storex.chats.saveChat(chat)
      })
    },

    addTag(tagName) {
      if (!tagName || !this.activeChat) return
      this.activeChat.tags = [...new Set([...(this.activeChat.tags || []), tagName])]
      this.$storex.chats.saveChat(this.activeChat)
    },

    executeCreateSubtasks(instructions) {
      if (this.activeChat) {
        this.$storex.projects.createSubTasks({
          chat: this.activeChat,
          instructions
        })
      }
    },

    setChatProject(project) {
      if (!this.activeChat) return
      this.activeChat.project_id = project.project_id
      this.$storex.chats.saveChat(this.activeChat)
    },

    onAddProfile(profile) {
      // Profile handling logic
    },

    onPRComment({ chat, title, files, description, profiles, mode, column }) {
      this.$emit('comment', { chat, title, files, description, profiles, mode, column })
    },

    onChangeColumnFromPR({ chats, column }) {
      this.$emit('change-column', { chats, column })
    },

    onNewChatFromChanges(payload) {
      this.$emit('new-chat', payload)
    },

    onPRChatMessage({ file }) {
      if (file.chat?.messages) {
        file.chat.messages.push({})
      }
    },

    async onDeleteChat(chatToDelete) {
      if (!chatToDelete) return

      // If deleting a child chat, set parent as active
      if (this.activeChildChat?.id === chatToDelete.id) {
        this.activeChildChat = null
        if (this.activeChat) {
          await this.$storex.chats.setActiveChat(this.activeChat)
        }
      }
      // If deleting parent chat, navigate to board
      else if (this.activeChat?.id === chatToDelete.id) {
        await this.$storex.chats.deleteChat(chatToDelete)
        this.navigateToBoard()
        return
      }

      // Delete the chat
      await this.$storex.chats.deleteChat(chatToDelete)
    }
  }
}
</script>
```

## Summary of Changes

1. **ChatPanel**: Now passes both `chat` (parent) and `activeChat` to header, emits delete events
2. **ChatPanelHeader**: 
   - Receives `activeChat` prop to track parent chat
   - Added delete menu item with error styling
   - Added delete confirmation modal with Cancel/Delete buttons
   - Resets confirmation state when chat changes
3. **VibeCodingView**:
   - Handles `onDeleteChat` method
   - Sets parent chat as active when deleting child chat
   - Navigates to board when deleting parent chat
   - Proper cleanup of `activeChildChat` state

# Solution: Simplify Chat Management in ChatPanel

The issue is that **ChatPanel should work with a single `chat` reference**, not juggling both `chat` and `childChat` with separate `activeChat`. When a chat is deleted, the event propagates to VibeCodingView which handles parent/board navigation using the store.

