    },
    hiddenCount() {
      return (this.chat?.messages || []).filter(m => m.hide).length
    },
  },
  watch: {
    chat(newChat, oldChat) {
      if (newChat?.id !== oldChat?.id) {
        this.showSearch = false
        this.chatSearch = ''
        this.showDeleteConfirm = false
      }
    },
    filter(val) {
      this.chatSearch = val
    }
