      this.$storex.chats.saveChat(this.chat)
    },

    clearSearch() {
      this.chatSearch = ''
      this.$emit('update:search', '')
    },

    confirmDelete() {
      if (!this.chat) return
      this.showDeleteConfirm = false
      this.$emit('delete-chat', this.chat)
    }
  }
}
