      <i class="fa-solid fa-spinner text-4xl animate-spin"></i>
      <span class="text-sm">Loading branches...</span>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    chat: { type: Object, default: null }
  },
  emits: ['refresh', 'select-branch', 'comment', 'change-column', 'new-chat', 'chat-message'],
  data() {
    return {
      selectedProjectId: null,
      currentBranch: 'main',
      compareBranch: 'local',
      availableBranches: [],
      loadingBranches: false,
      branchesLoaded: false,
      projectBranchCache: {} // Cache branches per project
    }
  },
  computed: {
    activeChat() {
      return this.chat
    },

    // Get all projects used in this chat and its subtasks
    projectsList() {
      if (!this.chat) return []

      const projects = new Map()
      const chatsToProcess = [this.chat]

      // Collect the active chat and all subtasks
      const allChats = this.$storex.chats.allChats || []
      const subtasks = allChats.filter(c => c.parent_id === this.chat.id)
      chatsToProcess.push(...subtasks)

      // Extract unique projects
      chatsToProcess.forEach(c => {
        if (c.project_id) {
          const proj = this.$storex.projects.allProjectsById?.[c.project_id]
          if (proj) {
            projects.set(c.project_id, proj)
          }
        }
      })

      return Array.from(projects.values())
    },

    selectedProject() {
      if (!this.selectedProjectId) return null
      return this.$storex.projects.allProjectsById?.[this.selectedProjectId] || null
    }
  },

  watch: {
    chat(newChat) {
      if (newChat?.id) {
        this.initializeProjectSelection()
      }
    },

    selectedProjectId(newProjectId) {
      if (newProjectId) {
        this.loadProjectBranches(newProjectId)
        this.loadBranchConfigForProject(newProjectId)
      }
    }
  },

  mounted() {
    this.initializeProjectSelection()
  },

  methods: {
    initializeProjectSelection() {
      if (!this.chat) return

      // Select the primary project (chat's project)
      this.selectedProjectId = this.chat.project_id

      // Load branches for the primary project
      if (this.selectedProjectId) {
        this.loadProjectBranches(this.selectedProjectId)
        this.loadBranchConfigForProject(this.selectedProjectId)
      }
    },

    async loadProjectBranches(projectId) {
      if (this.projectBranchCache[projectId]) {
        this.availableBranches = this.projectBranchCache[projectId]
        this.branchesLoaded = true
        return
      }

      this.loadingBranches = true
      this.branchesLoaded = false

      try {
        const branches = await this.$storex.projects.loadProjectBranches(projectId)
        this.projectBranchCache[projectId] = branches || []
        this.availableBranches = this.projectBranchCache[projectId]
      } catch (error) {
        console.error('Failed to load branches:', error)
        this.availableBranches = []
      } finally {
        this.loadingBranches = false
        this.branchesLoaded = true
      }
    },

    loadBranchConfigForProject(projectId) {
      if (!this.chat?.meta_data) return

      // Load branch config from chat metadata
      const projectConfig = this.chat.meta_data.projects?.[projectId]
      if (projectConfig) {
        this.currentBranch = projectConfig.current_branch || 'main'
        this.compareBranch = projectConfig.compare_branch || 'local'
      } else {
        this.currentBranch = 'main'
        this.compareBranch = 'local'
      }
    },

    onBranchChanged(branch) {
      this.currentBranch = branch
      this.saveBranchConfig()
    },

    onCompareBranchChanged(branch) {
      this.compareBranch = branch
      this.saveBranchConfig()
    },

    onBranchSelected({ fromBranch, toBranch }) {
      this.currentBranch = toBranch
      this.compareBranch = fromBranch
      this.saveBranchConfig()
      this.$emit('select-branch', { fromBranch, toBranch })
    },

    saveBranchConfig() {
      if (!this.chat || !this.selectedProjectId) return

      const updatedChat = {
        ...this.chat,
        meta_data: {
          ...(this.chat.meta_data || {}),
          projects: {
            ...(this.chat.meta_data?.projects || {}),
            [this.selectedProjectId]: {
              current_branch: this.currentBranch,
              compare_branch: this.compareBranch
            }
          }
        }
      }

      this.$storex.chats.saveChat(updatedChat)
    }
  }
}
</script>
