<script>
export default {
  props: {
    chat: { type: Object, default: null }
  },
  emits: ['refresh', 'select-branch', 'comment', 'change-column', 'new-chat', 'chat-message'],
  data() {
    return {
      selectedProjectId: null,
      currentBranch: 'main',
      compareBranch: 'local',
      availableBranches: [],
      loadingBranches: false,
      branchesLoaded: false,
      projectBranchCache: {}
    }
  },
  computed: {
    activeChat() {
      return this.chat
    },
    projectsList() {
      if (!this.chat) return []

      const projects = new Map()
      const chatsToProcess = [this.chat]

      const allChats = this.$storex.chats.allChats || []
      const subtasks = allChats.filter(c => c.parent_id === this.chat.id)
      chatsToProcess.push(...subtasks)

      chatsToProcess.forEach(c => {
        const chatId = this.chatId(c) 
        if (chatId) {
          const proj = this.$storex.projects.allProjectsById?.[chatId]
          if (proj) {
            projects.set(chatId, proj)
          }
        }
      })

      return Array.from(projects.values())
    },

    selectedProject() {
      if (!this.selectedProjectId) return null
      return this.$storex.projects.allProjectsById?.[this.selectedProjectId] || null
    }
  },

  watch: {
    chat(newChat) {
      if (newChat?.id) {
        this.initializeProjectSelection()
      }
    },

    selectedProjectId(newProjectId) {
      if (newProjectId) {
        this.loadProjectBranches(newProjectId)
        this.loadBranchConfigForProject(newProjectId)
      }
    }
  },

  mounted() {
    this.initializeProjectSelection()
  },

  methods: {
    chatId({ project_id, owner_project_id }) {
      return project_id || owner_project_id
    },

    initializeProjectSelection() {
      if (!this.chat) {
        this.branchesLoaded = false
        this.selectedProjectId = null
        return
      }

      this.selectedProjectId = this.chatId(this.chat)

      if (this.selectedProjectId) {
        this.loadProjectBranches(this.selectedProjectId)
        this.loadBranchConfigForProject(this.selectedProjectId)
      } else {
        this.branchesLoaded = false
      }
    },

    async loadProjectBranches(projectId) {
      if (!projectId) {
        this.branchesLoaded = false
        return
      }

      if (this.projectBranchCache[projectId]) {
        this.availableBranches = this.projectBranchCache[projectId]
        this.branchesLoaded = true
        return
      }

      this.loadingBranches = true
      this.branchesLoaded = false

      try {
        const branches = await this.$storex.projects.loadProjectBranches(projectId)
        this.projectBranchCache[projectId] = branches || []
        this.availableBranches = this.projectBranchCache[projectId]
        this.branchesLoaded = true
      } catch (error) {
        console.error('Failed to load branches:', error)
        this.availableBranches = []
        this.branchesLoaded = true
      } finally {
        this.loadingBranches = false
      }
    },

    async refreshBranches() {
      if (!this.selectedProjectId || this.loadingBranches) return

      this.loadingBranches = true

      try {
        const project = this.selectedProject
        if (!project) return

        // Use the project.$api to load branches
        const api = this.$storex.projects.$api
        const branches = await api.repo.branches()

        this.projectBranchCache[this.selectedProjectId] = branches || []
        this.availableBranches = this.projectBranchCache[this.selectedProjectId]

        // Ensure current branch still exists in the new list
        if (!this.availableBranches.includes(this.currentBranch)) {
          this.currentBranch = this.availableBranches[0] || 'main'
        }
      } catch (error) {
        console.error('Failed to refresh branches:', error)
        this.$toast.error('Failed to load branches from project')
      } finally {
        this.loadingBranches = false
      }
    },

    loadBranchConfigForProject(projectId) {
      if (!this.chat?.meta_data) {
        this.currentBranch = 'main'
        this.compareBranch = 'local'
        return
      }

      const projectConfig = this.chat.meta_data.projects?.[projectId]
      if (projectConfig) {
        this.currentBranch = projectConfig.current_branch || 'main'
        this.compareBranch = projectConfig.compare_branch || 'local'
      } else {
        this.currentBranch = 'main'
        this.compareBranch = 'local'
      }
    },

    onBranchChanged(branch) {
      this.currentBranch = branch
      this.saveBranchConfig()
    },

    onCompareBranchChanged(branch) {
      this.compareBranch = branch
      this.saveBranchConfig()
    },

    onBranchSelected({ fromBranch, toBranch }) {
      this.currentBranch = toBranch
      this.compareBranch = fromBranch
      this.saveBranchConfig()
      this.$emit('select-branch', { fromBranch, toBranch })
    },

    saveBranchConfig() {
      if (!this.chat || !this.selectedProjectId) return

      const updatedChat = {
        ...this.chat,
        meta_data: {
          ...(this.chat.meta_data || {}),
          projects: {
            ...(this.chat.meta_data?.projects || {}),
            [this.selectedProjectId]: {
              current_branch: this.currentBranch,
              compare_branch: this.compareBranch
            }
          }
        }
      }

      this.$storex.chats.saveChat(updatedChat)
    }
  }
}
</script>
```

**Changes made:**
- Added a "Load Branches" button (`fa-rotate-right`) in the header next to the "Refresh changes" button
- The button uses `api.repo.branches()` from the project's API to fetch fresh branch list
- Button is disabled while loading (`loadingBranches` state)
- Shows animated spinner when loading branches
- Updates the `projectBranchCache` with fresh data
- Validates that `currentBranch` still exists in the new branch list
- Clears the cache for the selected project before reloading to ensure fresh data
- Added error toast notification if branch loading fails

Use the main chat to store the branches info per project.
Main chat can have subtasks and affect multiple projects, use the main chat "meta_data" to store the branch info like:


```json
 meta_data: {
    ...meta_data,
    pull_requests: {
        "project_id": { url:"", fromBranch: "", toBranch: "" }
   }
}
```

